#include <vector>

// Given length n and array b (0-indexed), compute prefix XOR.
// Returns {0} if impossible, else {1, count, indices...} as per the defined construction.
std::vector<long long> solveXorOps(long long n, const std::vector<long long>& b) {
    std::vector<long long> a(n + 1, 0);
    for (long long i = 1; i <= n; ++i) {
        a[i] = a[i - 1] ^ b[i - 1];
    }

    // Overall XOR must be zero.
    if (a[n] != 0) {
        return {0};
    }

    // Special case n == 1.
    if (n == 1) {
        return {1, 0};
    }

    // Special case n == 2.
    if (n == 2) {
        if (a[1] == 0) {
            // Both elements are equal (since XOR 0), one merge at position 1.
            return {1, 1, 1};
        } else {
            return {0};
        }
    }

    std::vector<long long> result;
    result.push_back(1); // YES sentinel

    if (n % 2 == 1) {
        // Odd n: always possible.
        long long count = n - 2;
        result.push_back(count);
        for (long long i = 1; i <= n / 2; ++i) {
            result.push_back(2 * i - 1);
        }
        for (long long i = n / 2 - 1; i >= 1; --i) {
            result.push_back(2 * i - 1);
        }
        return result;
    } else {
        // Even n: need an odd prefix XOR zero.
        long long x = 0;
        for (long long i = 1; i <= n / 2; ++i) {
            if (a[2 * i - 1] == 0) {
                x = 2 * i - 1;
            }
        }
        if (x == 0) {
            return {0};
        }

        long long count = n - 4 + (x == 1 ? 1 : 0) + (x == n - 1 ? 1 : 0);
        result.push_back(count);

        // Left part: odd indices 1,3,...,x-2 then x-4,x-6,...,1
        for (long long i = 1; i <= x / 2; ++i) {
            result.push_back(2 * i - 1);
        }
        for (long long i = x / 2 - 1; i >= 1; --i) {
            result.push_back(2 * i - 1);
        }

        // Right part: even indices x+1, x+3,..., n-2 then n-4,...,x+2
        for (long long i = x / 2 + 1; i <= n / 2 - 1; ++i) {
            result.push_back(2 * i);
        }
        for (long long i = n / 2 - 2; i >= x / 2 + 1; --i) {
            result.push_back(2 * i);
        }

        return result;
    }
}
